script:
# التحقق من الحقول الأساسية
if not doc.opportunity_type:
    frappe.throw("يجب تحديد نوع الفرصة / Opportunity Type is required")

if not doc.pipeline_am:
    frappe.throw("يجب تعيين Pipeline AM")

if not doc.assigned_to:
    frappe.throw("يجب تعيين المستخدم المسؤول / Assigned To is required")

if not doc.customer:
    frappe.throw("يجب تحديد العميل / Customer is required")

# التحقق من نوع الفرصة
if doc.opportunity_type == "Renewal" and not doc.expected_revenue:
    frappe.throw("يجب إدخال Expected Revenue لفرص التجديد")

# تعيين Status تلقائياً عند الإنشاء
if doc.is_new():
    doc.status = "Lead"

# التحقق من الحقول الأساسية
if not doc.opportunity:
    frappe.throw("يجب ربط Qualification بفرصة بيع / Opportunity is required")

if not doc.qualified:
    frappe.throw("يجب تحديد نتيجة التأهيل / Qualified field is required")

# التحقق من Reason Code عند Not Qualified
if doc.qualified == "No" and not doc.reason_code:
    frappe.throw("يجب إدخال سبب عدم التأهيل / Reason Code is required")

# التحقق من البيانات الأساسية
if not doc.ttm_volume:
    frappe.throw("يجب إدخال TTM Volume")

if not doc.yoy_growth_:
    frappe.throw("يجب إدخال YOY Growth %")

# تحديث Status في الـ Opportunity تلقائياً
if doc.opportunity and doc.qualified:
    opp = frappe.get_doc("Sabre Sales Opportunity", doc.opportunity)
    
    if doc.qualified == "Yes":
        opp.status = "Business Case"
        frappe.msgprint(
            f"✅ تم تأهيل الفرصة {doc.opportunity} وتحويلها إلى Business Case"
        )
    elif doc.qualified == "No":
        opp.status = "Closed - Lost"
        frappe.msgprint(
            f"❌ تم إغلاق الفرصة {doc.opportunity} — السبب: {doc.reason_code}"
        )
    
    opp.save(ignore_permissions=True)
